        if (offset + 8 > classFileBuffer.length) {
            throw new IllegalArgumentException("Offset + 8 exceeds the buffer length");
        }
        return (((long)readInt(offset) & 0xFFFFFFFFL) << 32) | (readInt(offset + 4) & 0xFFFFFFFFL);
    }

    private int readInt(final int offset) {
        if (offset + 4 > classFileBuffer.length) {
            throw new IllegalArgumentException("Offset + 4 exceeds the buffer length");
        }
        return (classFileBuffer[offset] & 0xFF) << 24 |
               (classFileBuffer[offset + 1] & 0xFF) << 16 |
               (classFileBuffer[offset + 2] & 0xFF) << 8 |
               (classFileBuffer[offset + 3] & 0xFF);
    }

    public static void main(String[] args) {
