public class ByteVector {
    byte[] data;
    int length;

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        int requiredCapacity = this.length + byteLength;
        if (requiredCapacity > data.length) {
            enlarge(requiredCapacity - this.length);
        }

        if (byteArrayValue == null) {
            Arrays.fill(data, this.length, requiredCapacity, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, this.length, byteLength);
        }

        this.length = requiredCapacity;
        return this;
    }

    private void enlarge(int size) {
        int newCapacity = data.length * 2;
        if (newCapacity < data.length + size) {
            newCapacity = data.length + size;
        }
        data = Arrays.copyOf(data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(new byte[]{1, 2, 3, 4, 5}, 0, 5);
        System.out.println(Arrays.toString(bv.data));
        bv.putByteArray(null, 0, 5);
        System.out.println(Arrays.toString(bv.data));
    }
