import java.io.IOException;

public class HeaderParser {

    /** 
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        int index = end;
        while (index < headerPart.length() - 1) {
            if (headerPart.charAt(index) == '\r' && headerPart.charAt(index + 1) == '\n') {
                return index;
            }
            index++;
        }
        return -1; // Return -1 if no \r\n is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String headers = "Header1: Value1\r\nHeader2: Value2\r\n";
        int endOfFirstLine = parser.parseEndOfLine(headers, 0);
        System.out.println("End of first line at index: " + endOfFirstLine);
    }
}

