import java.util.Iterator;
import java.util.Set;

public class GraphTraversal<V, E> implements Iterator<V> {
    private Set<V> visited;
    private Set<V> vertices;

    public GraphTraversal(Set<V> vertices) {
        this.vertices = vertices;
        this.visited = new java.util.HashSet<>();
    }

    @Override
    public boolean hasNext() {
        return !visited.containsAll(vertices);
    }

    @Override
    public V next() {
        for (V vertex : vertices) {
            if (!visited.contains(vertex)) {
                visited.add(vertex);
                return vertex;
            }
        }
        throw new java.util.NoSuchElementException();
    }

    public static void main(String[] args) {
        Set<String> vertices = Set.of("A", "B", "C");
        GraphTraversal<String, String> traversal = new GraphTraversal<>(vertices);

        while (traversal.hasNext()) {
            System.out.println(traversal.next());
        }
    }
}

