public class Edge {
    private Edge next;
    private Edge prev;
    private List<Edge> treeEdges;

    public Edge(List<Edge> treeEdges) {
        this.treeEdges = treeEdges;
    }

    public void removeFromTreeEdgeList() {
        if (prev != null) {
            prev.next = next;
        } else {
            // This is the head of the list
            treeEdges.set(0, next);
        }
        if (next != null) {
            next.prev = prev;
        }
        prev = null;
        next = null;
    }

    public static void main(String[] args) {
        List<Edge> treeEdges = new LinkedList<>();
        Edge edge1 = new Edge(treeEdges);
        Edge edge2 = new Edge(treeEdges);
        Edge edge3 = new Edge(treeEdges);

        treeEdges.add(edge1);
        treeEdges.add(edge2);
        treeEdges.add(edge3);

        edge1.next = edge2;
        edge2.prev = edge1;
        edge2.next = edge3;
        edge3.prev = edge2;

        edge2.removeFromTreeEdgeList(); // Remove edge2 from the list

        // Verify removal
        System.out.println(treeEdges.size()); // Should print 2
        System.out.println(treeEdges.get(0) == edge1); // Should print true
        System.out.println(edge1.next == edge3); // Should print true
        System.out.println(edge3.prev == edge1); // Should print true
    }
}

