public class Graph<V> {
    private Map<V, Map<V, Double>> edges;

    public Graph() {
        edges = new HashMap<>();
    }

    public void addEdge(V from, V to, double weight) {
        edges.computeIfAbsent(from, k -> new HashMap<>()).put(to, weight);
    }

    public double vertexWeight(V v) {
        double weightSum = 0.0;
        for (Map<V, Double> edgeMap : edges.values()) {
            if (edgeMap.containsKey(v)) {
                weightSum += edgeMap.get(v);
            }
        }
        return weightSum;
    }

    public static void main(String[] args) {
        Graph<String> graph = new Graph<>();
        graph.addEdge("A", "B", 2.0);
        graph.addEdge("C", "B", 3.0);
        graph.addEdge("B", "D", 4.0);

        System.out.println(graph.vertexWeight("B")); // Output should be 5.0
    }
}

