protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }

    List<V> path = new ArrayList<>();
    V start = null;
    V current = null;

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (start == null) {
            start = source;
            current = source;
            path.add(source);
        }

        if (current.equals(source)) {
            path.add(target);
            current = target;
        } else if (current.equals(target)) {
            path.add(source);
            current = source;
        }
    }

    // Ensure the path is a cycle by checking if the last vertex is the same as the start
    if (!path.get(0).equals(path.get(path.size() - 1))) {
        return null; // Not a valid cycle
    }

    return new GraphPathImpl<>(graph, start, current, tour, 0.0); // Assuming weight is not needed
}

