     */
    public int nonZeros(int row) {
        if (row < 0 || row >= data.size()) {
            throw new IllegalArgumentException("Row index out of bounds");
        }
        int count = 0;
        for (int entry : data.get(row)) {
            if (entry != 0) {
                count++;
            }
        }
        return count;
    }

