private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b1 = bb.get() & 0xFF;
        if ((b1 & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b1);
            i++;
        } else if ((b1 & 0xE0) == 0xC0) {
            // Two-byte character
            if (!bb.hasRemaining()) break;
            int b2 = bb.get() & 0xFF;
            sb.append((char) ((b1 & 0x1F) << 6 | (b2 & 0x3F)));
            i += 2;
        } else if ((b1 & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() < 2) break;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            sb.append((char) ((b1 & 0x0F) << 12 | (b2 & 0x3F) << 6 | (b3 & 0x3F)));
            i += 3;
        } else if ((b1 & 0xF8) == 0xF0) {
            // Four-byte character
            if (bb.remaining() < 3) break;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            int codePoint = ((b1 & 0x07) << 18 | (b2 & 0x3F) << 12 | (b3 & 0x3F) << 6 | (b4 & 0x3F));
            sb.append(Character.toChars(codePoint));
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return i;
}

