import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

public class ClassFileBuffer {
    private byte[] buffer;

    public void readFrom(final InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] dataBuffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = in.read(dataBuffer, 0, 1024)) != -1) {
            baos.write(dataBuffer, 0, bytesRead);
        }
        buffer = baos.toByteArray();
    }

    public byte[] getBuffer() {
        return buffer;
    }

    public static void main(String[] args) {
        // Example usage
        try {
            ClassFileBuffer classFileBuffer = new ClassFileBuffer();
            classFileBuffer.readFrom(ClassFileBuffer.class.getResourceAsStream("/example.class"));
            System.out.println("Buffer length: " + classFileBuffer.getBuffer().length);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

