import java.lang.Character;

public class StringUtils {
    /** 
     * Trim trailing whitespace from the given String.
     * @param str the String to check
     * @return the trimmed String
     * @see java.lang.Character#isWhitespace
     */
    public static String trimTrailingWhitespace(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        int end = str.length() - 1;
        while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
            end--;
        }
        return str.substring(0, end + 1);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println("'" + trimTrailingWhitespace("   Hello World   ") + "'"); // '   Hello World'
        System.out.println("'" + trimTrailingWhitespace("Hello World   ") + "'");    // 'Hello World'
        System.out.println("'" + trimTrailingWhitespace("Hello World") + "'");       // 'Hello World'
        System.out.println("'" + trimTrailingWhitespace("   ") + "'");              // ''
        System.out.println("'" + trimTrailingWhitespace("") + "'");                // ''
        System.out.println("'" + trimTrailingWhitespace(null) + "'");              // null
    }
}

