public class PropertyFinder {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        return substituteVars(value, props);
    }

    private static String substituteVars(String value, Properties props) {
        StringBuilder result = new StringBuilder();
        int start = 0;
        int end;
        while ((end = value.indexOf("${", start)) != -1) {
            result.append(value.substring(start, end));
            int closeIndex = value.indexOf("}", end + 2);
            if (closeIndex == -1) {
                throw new IllegalArgumentException("Unclosed variable substitution in: " + value);
            }
            String varName = value.substring(end + 2, closeIndex);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            }
            start = closeIndex + 1;
        }
        result.append(value.substring(start));
        return result.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");

        String result = findAndSubst("greeting", props);
        System.out.println(result);  // Output: Hello, World!
    }
}

