import java.util.List;
import java.util.ArrayList;

class Node {
    boolean isActive;
    List<Node> children;

    Node(boolean isActive) {
        this.isActive = isActive;
        this.children = new ArrayList<>();
    }
}

class CategoryTree {
    Node root;

    CategoryTree(Node root) {
        this.root = root;
    }

    protected int removeUnusedNodes() {
        if (root == null) {
            return 0;
        }
        return removeUnusedNodes(root) - 1; // Subtract 1 to not count the root itself as removed
    }

    private int removeUnusedNodes(Node node) {
        List<Node> toRemove = new ArrayList<>();
        for (Node child : node.children) {
            if (child.isActive) {
                removeUnusedNodes(child);
            } else {
                toRemove.add(child);
            }
        }
        node.children.removeAll(toRemove);
        return toRemove.size() + (node.isActive ? 0 : 1);
    }

    public static void main(String[] args) {
        // Example usage
        Node root = new Node(true);
        root.children.add(new Node(false));
        root.children.add(new Node(true));
        root.children.get(1).children.add(new Node(false));
        root.children.get(1).children.add(new Node(true));

        CategoryTree tree = new CategoryTree(root);
        int removedNodes = tree.removeUnusedNodes();
        System.out.println("Removed nodes: " + removedNodes);
    }
}

