import java.util.HashMap;
import java.util.Map;
import java.util.Set;

public class Mappings {
    private Map<String, Map<String, Object>> properties;

    public Mappings() {
        this.properties = new HashMap<>();
    }

    public void addField(String field, Map<String, Object> config) {
        properties.put(field, config);
    }

    public Map<String, Map<String, Object>> getProperties() {
        return properties;
    }

    public Mappings diffStructure(String tableName, Mappings mappings) {
        Mappings diff = new Mappings();
        for (Map.Entry<String, Map<String, Object>> entry : this.properties.entrySet()) {
            String field = entry.getKey();
            if (!mappings.properties.containsKey(field) && !field.equals("_source")) {
                diff.addField(field, entry.getValue());
            }
        }
        return diff;
    }

    public static void main(String[] args) {
        Mappings currentMappings = new Mappings();
        currentMappings.addField("field1", new HashMap<>());
        currentMappings.addField("field2", new HashMap<>());
        currentMappings.addField("_source", new HashMap<>());

        Mappings historyMappings = new Mappings();
        historyMappings.addField("field1", new HashMap<>());

        Mappings diff = currentMappings.diffStructure("table1", historyMappings);
        System.out.println(diff.getProperties());
    }
}

