import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[32];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        if (byteArrayValue == null) {
            ensureCapacity(byteLength);
            Arrays.fill(data, length, length + byteLength, (byte) 0);
            length += byteLength;
        } else {
            ensureCapacity(byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
            length += byteLength;
        }
        return this;
    }

    private void ensureCapacity(int additionalCapacity) {
        int requiredCapacity = length + additionalCapacity;
        if (requiredCapacity > data.length) {
            int newCapacity = Math.max(data.length * 2, requiredCapacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byte[] bytes = {1, 2, 3, 4, 5};
        byteVector.putByteArray(bytes, 1, 3);
        System.out.println(Arrays.toString(byteVector.data));
    }
}

