import java.util.Stack;

public class FrameStackManager {
    private Stack<String> outputFrameStack;

    public FrameStackManager() {
        this.outputFrameStack = new Stack<>();
    }

    private void pop(final String descriptor) {
        int index = 0;
        if (descriptor.charAt(0) == '(') {
            // Method descriptor, skip '('
            index++;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
            // Skip ')'
            index++;
        }
        // If it's a field descriptor, pop the single type
        if (index == 0) {
            popType(descriptor, index);
        }
    }

    private int popType(final String descriptor, int index) {
        switch (descriptor.charAt(index)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                outputFrameStack.pop();
                return index + 1;
            case 'J': case 'D':
                outputFrameStack.pop();
                outputFrameStack.pop(); // double and long take two slots
                return index + 1;
            case 'L':
                // Object type, skip to the end of the class name
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                outputFrameStack.pop();
                return index + 1;
            case '[':
                // Array type, skip all '[' and then skip the type
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                return popType(descriptor, index) - 1; // Adjust for the extra increment in the loop
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }

    public static void main(String[] args) {
        FrameStackManager manager = new FrameStackManager();
        // Example usage
        manager.outputFrameStack.push("I");
        manager.outputFrameStack.push("Ljava/lang/String;");
        manager.outputFrameStack.push("D");
        manager.pop("(ILjava/lang/String;)D");
        System.out.println(manager.outputFrameStack); // Should be empty
    }
}

