public class ProtobufInputStream {
    private InputStream in;
    private int buffer = 0;
    private int bufferCount = 0;

    public ProtobufInputStream(InputStream in) {
        this.in = in;
    }

    public int readTag() throws IOException {
        if (bufferCount == 0) {
            buffer = in.read();
            if (buffer == -1) {
                return 0; // End of stream
            }
            bufferCount = 7;
